"""Builds sql/schema.sql = every migration in order, with a header. Run: python tools/build_schema.py

The file is for reading and for creating a database by hand (psql -f). The app itself applies migrations/ on start.
tests/test_schema_files.py fails if this file is stale or differs from what the migrations create.
"""
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
HEADER = """-- StudioDesk - complete PostgreSQL schema (generated by tools/build_schema.py from migrations/*.sql).
-- Do not edit by hand: add the next migrations/NNN_name.sql and rebuild.
--
-- Create a database by hand (the API does this itself when it starts, so this is optional):
--   psql "$PG_DSN" -v ON_ERROR_STOP=1 -c 'CREATE SCHEMA spa' -c 'SET search_path TO spa' -f sql/schema.sql
-- It also records the migrations as applied, so the API will not try to run them again.
-- Needs the btree_gist extension (bundled with PostgreSQL; creating it needs the database owner).
-- Column-by-column documentation: docs/schema.md
"""


def build() -> str:
    files = sorted((ROOT / "migrations").glob("*.sql"))
    parts = [HEADER]
    for f in files:
        parts.append(f"\n-- ======== {f.name} ========\n{f.read_text().rstrip()}\n")
    versions = ",\n  ".join(f"('{f.name}')" for f in files)
    parts.append(f"""
-- ======== migration bookkeeping (same table app/migrate.py uses) ========
CREATE TABLE IF NOT EXISTS schema_migrations(
  version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES
  {versions}
ON CONFLICT DO NOTHING;
""")
    return "".join(parts)


if __name__ == "__main__":
    (ROOT / "sql").mkdir(exist_ok=True)
    (ROOT / "sql" / "schema.sql").write_text(build())
    print("wrote sql/schema.sql")
